"""Existing equipment records and interval helpers. Times are minutes after midnight."""

def overlaps(start, end, other_start, other_end):
    return start < other_end and other_start < end


def occupied_units_at(reservations, minute):
    return sum(
        row['units']
        for row in reservations
        if row['status'] == 'confirmed' and row['start'] <= minute < row['end']
    )


def serviceable_units(fleet):
    return fleet['total_units'] - fleet['out_of_service_units']
